CREATE TABLE IF NOT EXISTS runtime_snapshots (node_id CHAR(36) PRIMARY KEY, role VARCHAR(16) NOT NULL, frp_version VARCHAR(64) NOT NULL, collected_at BIGINT NOT NULL, bind_address VARCHAR(255) NOT NULL, bind_port INT NOT NULL, proxy_count INT NOT NULL, client_count INT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT fk_runtime_snapshot_node FOREIGN KEY(node_id) REFERENCES nodes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- statement
CREATE TABLE IF NOT EXISTS runtime_proxies (node_id CHAR(36) NOT NULL, name VARCHAR(255) NOT NULL, type VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, local_address VARCHAR(512) NOT NULL, remote_address VARCHAR(512) NOT NULL, last_error LONGTEXT NOT NULL, bytes_in BIGINT NOT NULL, bytes_out BIGINT NOT NULL, today_bytes_in BIGINT NOT NULL, today_bytes_out BIGINT NOT NULL, current_connections BIGINT NOT NULL, collected_at BIGINT NOT NULL, PRIMARY KEY(node_id,name), INDEX idx_runtime_proxies_filter(status,type,node_id,name), CONSTRAINT fk_runtime_proxy_node FOREIGN KEY(node_id) REFERENCES nodes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- statement
CREATE TABLE IF NOT EXISTS runtime_clients (node_id CHAR(36) NOT NULL, id VARCHAR(255) NOT NULL, address VARCHAR(512) NOT NULL, connected_at BIGINT NOT NULL, collected_at BIGINT NOT NULL, PRIMARY KEY(node_id,id), CONSTRAINT fk_runtime_client_node FOREIGN KEY(node_id) REFERENCES nodes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
